const BANK = [
// ---------------- s1 : la philosophie
{id:'q001',s:'s1',t:'qcm',q:'Quelle est la définition de la philosophie donnée en classe ?',o:['Un ensemble de connaissances scientifiques sur le monde','Une réflexion critique et rationnelle en quête de sens sur l\'existence humaine et sur le monde','Une tradition orale qui explique l\'origine des humains','L\'art de persuader les foules par le discours'],a:1,w:'Trois mots-clés : critique, rationnelle, quête de sens. La philosophie ne donne pas de réponses toutes faites.'},
{id:'q002',s:'s1',t:'qcm',q:'Que signifie « philo-sophia » ?',o:['La science du vrai','L\'amour ou le désir de la sagesse','La connaissance des dieux','L\'art du bon discours'],a:1,w:'Si on désire la sagesse, c\'est qu\'on ne l\'a pas : la philosophie est un état d\'être, pas un corps de connaissances.'},
{id:'q003',s:'s1',t:'qcm',q:'Pourquoi dit-on que la philosophie est un « état d\'être » plutôt qu\'un corps de connaissances ?',o:['Parce qu\'elle n\'a aucun contenu','Parce que désirer la sagesse implique qu\'on ne la possède pas','Parce qu\'elle refuse la raison','Parce qu\'elle est réservée aux universités'],a:1,w:'C\'est le raisonnement de la diapo « Philo-Sophia » : on désire ce qu\'on n\'a pas.'},
{id:'q004',s:'s1',t:'qcm',q:'Laquelle n\'est PAS une des cinq branches de la philosophie académique ?',o:['La métaphysique','L\'épistémologie','La rhétorique','L\'esthétique'],a:2,w:'Les cinq branches : métaphysique, esthétique, logique, éthique, épistémologie. La rhétorique est l\'art des sophistes.'},
{id:'q005',s:'s1',t:'qcm',q:'La philosophie est en opposition avec :',o:['La science','Les comportements irrationnels, émotifs ou impulsifs','La religion','L\'art et la poésie'],a:1,w:'La diapo « La philosophie » : elle s\'oppose aux comportements irrationnels, émotifs ou impulsifs. Elle n\'est pas l\'ennemie de la science (elle en est la source) ni de la religion ou de l\'art.'},
{id:'q006',s:'s1',t:'qcm',q:'Comment le cours définit-il la raison ?',o:['La faculté de percevoir le monde par les sens','La faculté humaine de connaître, de juger et d\'agir selon des principes clairs qui peuvent être justifiés logiquement','La capacité de persuader une foule','La mémoire des traditions d\'un peuple'],a:1,w:'Connaître, juger, agir, selon des principes justifiables logiquement.'},
{id:'q007',s:'s1',t:'vf',q:'« Rationnel » et « irrationnel » sont synonymes de « vrai » et « faux ».',a:false,w:'Faux. La religion, l\'art et la poésie peuvent donner accès à des vérités sans la raison. La rationalité est un chemin parmi d\'autres, mais elle est une exigence en philosophie et en science.'},
{id:'q008',s:'s1',t:'vf',q:'La philosophie académique est séparée en cinq grandes branches.',a:true,w:'Vrai : métaphysique, esthétique, logique, éthique et épistémologie.'},
{id:'q009',s:'s1',t:'vf',q:'Selon le cours, la philosophie donne des réponses toutes faites aux grandes questions.',a:false,w:'Faux. Elle nous encourage à remettre en question nos opinions et ne donne pas de réponses toutes faites.'},
{id:'q010',s:'s1',t:'courte',q:'Donne la définition de la philosophie et explique brièvement chacun de ses trois mots-clés.',m:'<p>La philosophie est une <b>réflexion critique et rationnelle en quête de sens sur l\'existence humaine et sur le monde</b>.</p><ul><li><b>Critique</b> : elle remet en question les opinions, elle ne donne pas de réponses toutes faites.</li><li><b>Rationnelle</b> : elle procède à l\'aide de la raison, contre les comportements émotifs ou impulsifs.</li><li><b>Quête de sens</b> : elle cherche le sens de notre existence et du monde.</li></ul>',k:['critique','rationnelle','quête de sens','existence','monde']},
{id:'q011',s:'s1',t:'courte',q:'Nomme les cinq branches de la philosophie académique et donne la question de chacune.',m:'<ul><li><b>Métaphysique</b> : qu\'est-ce qui existe vraiment, au-delà du physique ?</li><li><b>Esthétique</b> : qu\'est-ce que le beau, l\'art ?</li><li><b>Logique</b> : quelles sont les règles d\'un raisonnement valide ?</li><li><b>Éthique</b> : qu\'est-ce que le bien, la bonne action ?</li><li><b>Épistémologie</b> : qu\'est-ce que connaître, qu\'est-ce que la science ?</li></ul>',k:['métaphysique','esthétique','logique','éthique','épistémologie']},
{id:'q012',s:'s1',t:'courte',q:'Que veut dire « penser par soi-même » selon le cours 1 ? Utilise la notion d\'influences.',m:'<p>Nous sommes la <b>somme de nos influences</b> (famille, éducation, expériences, réseaux sociaux, publicité). Penser par soi-même, c\'est se demander <b>pourquoi</b> on pense ainsi et sur quelle base on justifie sa réflexion, afin de distinguer les opinions <b>indirectement justifiables</b> (héritées) des opinions <b>directement justifiables</b> (dont on peut donner les raisons). La philosophie permet de reconnaître ces influences, d\'explorer d\'autres visions du monde et de choisir son propre chemin.</p>',k:['influences','remettre en question','justifiables','choisir']},

// ---------------- s2 : philo, science, mythe
{id:'q020',s:'s2',t:'qcm',q:'Quelle est la différence entre la science et la philosophie selon le cours ?',o:['La science progresse (les nouvelles connaissances remplacent les vieilles), la philosophie pose des questions éternelles','La philosophie est empirique, la science est conceptuelle','La science est plus ancienne que la philosophie','Il n\'y a aucune différence'],a:0,w:'Science = progrès, savoir concret et empirique. Philosophie = questions éternelles, savoir conceptuel.'},
{id:'q021',s:'s2',t:'qcm',q:'Le savoir philosophique est :',o:['Concret et pratique','Empirique','Conceptuel','Technique'],a:2,w:'La science est un savoir concret, pratique et empirique; la philosophie est un savoir conceptuel.'},
{id:'q022',s:'s2',t:'qcm',q:'Dans la comparaison mythe et philosophie, le mythe explique le monde par des principes :',o:['Internes (immanence)','Externes (transcendance)','Mathématiques','Atomiques'],a:1,w:'Mythe : principes externes (transcendance), étude du surnaturel, plusieurs principes. Philosophie : principes internes (immanence), étude de la nature, économie des principes.'},
{id:'q023',s:'s2',t:'qcm',q:'Que signifie « économie des principes » ?',o:['Expliquer le plus de phénomènes avec le moins de principes possible','Expliquer le monde par l\'argent','Faire intervenir plusieurs dieux','Refuser toute explication'],a:0,w:'Les explications des présocratiques sont économiques et parcimonieuses : un nombre restreint de principes, parfois un seul, pour une multiplicité de phénomènes.'},
{id:'q024',s:'s2',t:'qcm',q:'« Les phénomènes naturels sont expliqués par l\'action de divinités. » Cette affirmation correspond à :',o:['La pensée mythique (Hésiode)','La pensée rationnelle (présocratiques)','Les deux','Aucune des deux'],a:0,w:'Activité de synthèse du cours 3, affirmation 1 : pensée mythique.'},
{id:'q025',s:'s2',t:'qcm',q:'« L\'univers possède une structure intelligible accessible à l\'enquête rationnelle. » Cette affirmation correspond à :',o:['La pensée mythique (Hésiode)','La pensée rationnelle (présocratiques)','Les deux','Aucune des deux'],a:1,w:'C\'est la deuxième innovation des présocratiques : la nature est intelligible, compréhensible en elle-même.'},
{id:'q026',s:'s2',t:'vf',q:'Pour la philosophie, la nature contient ses propres principes.',a:true,w:'Vrai : c\'est l\'immanence, par opposition à l\'ordre arbitraire imposé par les dieux dans le mythe.'},
{id:'q027',s:'s2',t:'vf',q:'La science et la philosophie utilisent toutes deux un savoir empirique fondé sur des instruments.',a:false,w:'Faux. La science est empirique; la philosophie est un savoir conceptuel, et les présocratiques n\'avaient aucun outil scientifique.'},
{id:'q028',s:'s2',t:'courte',q:'Donne deux différences entre la science et la philosophie.',m:'<ol><li>La <b>science</b> est un <b>progrès</b> : les nouvelles connaissances remplacent les vieilles. La <b>philosophie</b> pose des <b>questions éternelles</b> et remet sans cesse la réflexion en question.</li><li>La science est un savoir <b>concret, pratique et empirique</b>; la philosophie est un savoir <b>conceptuel</b>.</li></ol><p>Lien : la philosophie est la source des sciences modernes.</p>',k:['progrès','questions éternelles','empirique','conceptuel']},
{id:'q029',s:'s2',t:'courte',q:'Compare le mythe et la philosophie sur trois points.',m:'<table><tr><th>Mythe</th><th>Philosophie</th></tr><tr><td>Principes externes (transcendance)</td><td>Principes internes (immanence)</td></tr><tr><td>Étude du surnaturel (dieux)</td><td>Étude de la nature</td></tr><tr><td>Plusieurs principes</td><td>Économie des principes</td></tr></table>',k:['transcendance','immanence','surnaturel','nature','économie des principes']},
{id:'q030',s:'s2',t:'courte',q:'Quelle est la source principale de connaissance pour la pensée mythique et pour la pensée rationnelle ?',m:'<p><b>Pensée mythique</b> : la tradition orale, les poètes (Homère, Hésiode), l\'autorité et les rituels. <b>Pensée rationnelle</b> : l\'observation de la nature et le raisonnement (le logos).</p>',k:['tradition orale','poètes','observation','raisonnement']},

// ---------------- s3 : pensée mythique
{id:'q040',s:'s3',t:'qcm',q:'Lequel n\'est PAS un trait du mythe ?',o:['Tradition orale, récits non historiques','Fait intervenir des êtres surnaturels','Repose sur l\'observation et le raisonnement','Organise le temps'],a:2,w:'L\'observation et le raisonnement, c\'est la méthode des présocratiques.'},
{id:'q041',s:'s3',t:'qcm',q:'Pourquoi la religion dite primitive est-elle efficace selon le cours ?',o:['Parce qu\'elle repose sur la science','Parce qu\'elle se structure à partir de mythes et de rituels pour maintenir l\'ordre de l\'univers','Parce qu\'elle est écrite','Parce qu\'elle rejette les êtres surnaturels'],a:1,w:'Agir selon les prescriptions des êtres surnaturels devient le code moral et social.'},
{id:'q042',s:'s3',t:'qcm',q:'Qui a écrit la Théogonie ?',o:['Homère','Hésiode','Platon','Parménide'],a:1,w:'Hésiode : la Théogonie et Les Travaux et les Jours. Homère : l\'Iliade et l\'Odyssée.'},
{id:'q043',s:'s3',t:'qcm',q:'Dans la Théogonie, quelles sont les trois premières entités ?',o:['Zeus, Héra et Poséidon','Abîme (le Chaos), Gaïa (la Terre) et Éros (l\'Amour)','Ouranos, Pontos et Cronos','Les Titans, les Cyclopes et les Hécatonchires'],a:1,w:'Chaos, Gaïa, Éros; puis Ouranos (le Ciel) et Pontos (la Mer); puis les Titans, Titanides, Cyclopes et Hécatonchires.'},
{id:'q044',s:'s3',t:'qcm',q:'Dans Les Travaux et les Jours, qui ouvre la jarre contenant tous les malheurs ?',o:['Prométhée','Rhéia','Pandore','Gaïa'],a:2,w:'Pandore ouvre la jarre après que Zeus, en colère contre le vol du feu par Prométhée, envoie une malédiction aux humains.'},
{id:'q045',s:'s3',t:'qcm',q:'Quel est l\'ordre des races humaines chez Hésiode ?',o:['Fer, bronze, argent, or, héros','Or, argent, bronze, héros, fer','Or, bronze, argent, fer, héros','Héros, or, argent, bronze, fer'],a:1,w:'Or, argent, bronze, héros (demi-dieux), fer.'},
{id:'q046',s:'s3',t:'qcm',q:'Qu\'apportent Homère et Hésiode aux mythes ?',o:['Ils les inventent de toutes pièces','Ils les structurent par écrit, précisent l\'anthropomorphisme des dieux et éliminent des contradictions','Ils les dénoncent comme faux','Ils les remplacent par la science'],a:1,w:'Ils fixent des filiations cohérentes entre les divinités et ordonnent les luttes et alliances.'},
{id:'q047',s:'s3',t:'qcm',q:'Que donne Prométhée aux humains ?',o:['La jarre des malheurs','Le feu et la métallurgie','L\'écriture','La démocratie'],a:1,w:'Prométhée donne le feu et enseigne la métallurgie; Zeus se venge par une malédiction.'},
{id:'q048',s:'s3',t:'vf',q:'Homère a écrit la Théogonie.',a:false,w:'Faux. La Théogonie est d\'Hésiode.'},
{id:'q049',s:'s3',t:'vf',q:'Avant la philosophie, la pensée mythique était la principale source d\'information pour comprendre la réalité.',a:true,w:'Vrai, diapo « Naissance de la philosophie ».'},
{id:'q050',s:'s3',t:'vf',q:'Dans la Théogonie, c\'est Zeus qui établit l\'ordre définitif du monde après la guerre contre les Titans.',a:true,w:'Vrai : Zeus, roi des dieux et des humains, établit l\'ordre définitif du monde.'},
{id:'q051',s:'s3',t:'courte',q:'Nomme quatre caractéristiques du mythe.',m:'<p>Parmi les sept : tradition orale et récits non historiques; raconte l\'origine des êtres humains; explique la cause des phénomènes naturels mystérieux; fait intervenir des êtres surnaturels; propose des modèles exemplaires à valeur morale; organise le temps; donne du sens à la vie humaine.</p>',k:['tradition orale','origine','phénomènes naturels','surnaturels','morale','temps','sens']},
{id:'q052',s:'s3',t:'courte',q:'Résume la Théogonie d\'Hésiode en quatre étapes.',m:'<ol><li>Abîme (Chaos), Gaïa (Terre) et Éros (Amour); puis Ouranos (Ciel) et Pontos (Mer).</li><li>Naissance des Titans, Titanides, Cyclopes et Hécatonchires.</li><li>Zeus est caché par Rhéia chez Gaïa; guerre des Titans contre les Olympiens.</li><li>Zeus, roi des dieux et des humains, établit l\'ordre définitif du monde.</li></ol>',k:['Chaos','Gaïa','Éros','Titans','Zeus','Olympiens']},
{id:'q053',s:'s3',t:'courte',q:'Résume Les Travaux et les Jours d\'Hésiode (Prométhée, Pandore, les races).',m:'<p>Les premiers humains vivaient comme des dieux dans l\'abondance. Zeus demande à Prométhée de départager dieux et humains; Prométhée donne le feu et la métallurgie aux humains. Zeus, en colère, envoie une malédiction : Pandore ouvre la jarre et tous les malheurs se répandent. Suivent les races d\'or, d\'argent, de bronze, des héros et de fer.</p>',k:['Prométhée','feu','Pandore','jarre','or','argent','bronze','héros','fer']},
{id:'q054',s:'s3',t:'courte',q:'Qu\'est-ce que l\'anthropomorphisme des dieux et qui l\'a précisé par écrit ?',m:'<p>L\'anthropomorphisme consiste à donner aux dieux des traits humains : personnalités, traits physiques, qualités morales, passions, fonctions sociales. Ce sont <b>Homère et Hésiode</b> qui, en écrivant les mythes, ont précisé ce caractère anthropomorphique. Xénophane le critiquera.</p>',k:['traits humains','passions','Homère','Hésiode']},

// ---------------- s4 : du mythe à la raison
{id:'q060',s:'s4',t:'qcm',q:'Dans le passage du mythe à la raison, pourquoi cherche-t-on un nouveau procédé explicatif ?',o:['Parce que les dieux ont disparu','Parce que l\'ordre imposé par les dieux est arbitraire et rend mal compte de la stabilité du monde','Parce que les mythes étaient trop courts','Parce que l\'écriture n\'existait pas'],a:1,w:'L\'ordre divin est arbitraire; on cherche un procédé qui rende mieux compte de la stabilité et de l\'ordre du monde : la nature contient ses propres principes.'},
{id:'q061',s:'s4',t:'qcm',q:'Que devient le registre du discours explicatif quand on passe du mythe à la raison ?',o:['On raconte des histoires plus longues','On ne raconte plus d\'histoires : on cherche des règles générales, des lois, des principes','On chante des hymnes','On consulte les oracles'],a:1,w:'Nouveau registre de discours explicatif : règles générales, lois, principes.'},
{id:'q062',s:'s4',t:'vf',q:'L\'avènement de la pensée rationnelle a supprimé la pensée mythique.',a:false,w:'Faux. Un nouveau mode de pensée ne supprime pas les modes antérieurs : c\'est un ajout dans les outils d\'explication de la réalité.'},
{id:'q063',s:'s4',t:'courte',q:'Explique en quatre idées le passage du mythe à la raison.',m:'<ol><li>Nouveau registre de discours explicatif : on ne raconte plus d\'histoires.</li><li>L\'ordre imposé par les dieux est arbitraire.</li><li>On cherche donc un procédé explicatif qui rende mieux compte de la stabilité et de l\'ordre du monde.</li><li>La nature contient ses propres principes : règles générales, lois, principes.</li></ol>',k:['histoires','arbitraire','stabilité','ordre','propres principes','lois']},

// ---------------- s5 : présocratiques
{id:'q070',s:'s5',t:'qcm',q:'Laquelle est une des trois innovations fondamentales des présocratiques ?',o:['Les dieux causent les phénomènes naturels','La nature est un tout organisé rationnellement, source d\'intelligibilité','Le savoir est réservé aux prêtres','La vérité dépend de chacun'],a:1,w:'Les trois innovations : principes internes (immanents), nature intelligible et ordonnée, explications économiques.'},
{id:'q071',s:'s5',t:'qcm',q:'Pourquoi peut-on qualifier les présocratiques de premiers scientifiques de l\'histoire ?',o:['Ils utilisaient des instruments de mesure','Ils sont les premiers à nourrir une réflexion purement théorique (ni technique ni religieuse) sur la nature','Ils faisaient des expériences en laboratoire','Ils ont inventé l\'écriture'],a:1,w:'Réflexion purement théorique sur la nature. Mais méthode différente (spéculation, aucun outil) et intérêts différents (théologie, ontologie, morale).'},
{id:'q072',s:'s5',t:'qcm',q:'Lequel n\'est PAS un principe scientifique anticipé par les présocratiques selon le cours ?',o:['Le Big Bang','L\'évolution','La relativité d\'Einstein','L\'atome'],a:2,w:'Les quatre principes anticipés : le Big Bang, l\'évolution, l\'atome, la conservation de l\'énergie.'},
{id:'q073',s:'s5',t:'qcm',q:'Quelle est la méthode des présocratiques ?',o:['Spéculation formelle et rationnelle, sans outil scientifique','Expérimentation avec instruments','Révélation divine','Sondages d\'opinion'],a:0,w:'Textes discursifs et argumentatifs basés sur l\'observation et le raisonnement; spéculation formelle et rationnelle, aucun outil scientifique.'},
{id:'q074',s:'s5',t:'qcm',q:'Sur quoi portent les questions des présocratiques ?',o:['La justice et les lois','La nature : l\'univers matériel, le chaos primitif, l\'origine de l\'ordre','La rhétorique','La démocratie'],a:1,w:'Ils traitent de la nature et des premiers principes matériels (eau, air, feu, terre). Les questions sur la justice viendront avec les sophistes et Socrate.'},
{id:'q075',s:'s5',t:'qcm',q:'Quels sont les intérêts des présocratiques qui les distinguent des scientifiques modernes ?',o:['La technique et le commerce','La théologie, l\'ontologie et la morale','Le sport et la musique','La politique et le droit'],a:1,w:'Intérêts différents : théologie, ontologie, morale.'},
{id:'q076',s:'s5',t:'vf',q:'Les textes des présocratiques nous sont parvenus complets.',a:false,w:'Faux. Ils nous sont parvenus sous forme de fragments plus ou moins épars.'},
{id:'q077',s:'s5',t:'vf',q:'Selon le cours, les présocratiques ont anticipé la conservation de l\'énergie.',a:true,w:'Vrai, avec le Big Bang, l\'évolution et l\'atome.'},
{id:'q078',s:'s5',t:'vf',q:'Les présocratiques expliquent la nature par des principes dont on peut généralement faire l\'expérience.',a:true,w:'Vrai : c\'est la première innovation, des principes internes, immanents à la nature.'},
{id:'q079',s:'s5',t:'courte',q:'Explique les trois innovations fondamentales des présocratiques.',m:'<ol><li><b>Principes internes, immanents à la nature</b> : pour expliquer les phénomènes naturels, on fait intervenir des principes dont on peut faire l\'expérience, et non des dieux extérieurs.</li><li><b>La nature n\'est pas chaotique</b> : c\'est un tout organisé rationnellement, avec régularité et ordre; elle est intelligible, compréhensible en elle-même et non depuis un au-delà divin.</li><li><b>Explications économiques et parcimonieuses</b> : un nombre restreint de principes, parfois un seul, pour rendre compte d\'une multiplicité de phénomènes.</li></ol>',k:['internes','immanents','intelligible','ordre','économiques','un seul principe']},
{id:'q080',s:'s5',t:'courte',q:'Peut-on qualifier les présocratiques de premiers scientifiques ? Donne l\'argument pour et les deux réserves.',m:'<p><b>Oui</b> : ils sont les premiers à nourrir une réflexion purement théorique (ni technique ni religieuse) sur la nature, et ils ont anticipé le Big Bang, l\'évolution, l\'atome et la conservation de l\'énergie. <b>Cependant</b> : leur méthode est différente (spéculation formelle et rationnelle, aucun outil scientifique) et leurs intérêts sont différents (théologie, ontologie, morale).</p>',k:['théorique','anticipé','spéculation','aucun outil','théologie','ontologie','morale']},
{id:'q081',s:'s5',t:'courte',q:'Décris la méthode philosophique des présocratiques.',m:'<p>Ils observent la nature et raisonnent à partir de ce qu\'ils voient; ils écrivent des textes discursifs et argumentatifs (des raisons, pas des récits); ils cherchent un principe premier interne à la nature qui explique le reste; ils procèdent par spéculation formelle et rationnelle, sans instruments ni expériences.</p>',k:['observation','raisonnement','argumentatifs','principe premier','spéculation']},

// ---------------- s6 : présocratiques un par un
{id:'q090',s:'s6',t:'qcm',q:'Pour Pythagore, le principe de l\'univers est :',o:['Le feu','Le nombre','L\'eau','L\'atome'],a:1,w:'« Tout est nombre. » Pythagore est chef d\'un culte religieux qui vénère les nombres.'},
{id:'q091',s:'s6',t:'qcm',q:'Chez Pythagore, la justice correspond au nombre :',o:['1','7','9','10'],a:2,w:'Justice = 9, âme = 1, perfection du monde = 10, temps = 7.'},
{id:'q092',s:'s6',t:'qcm',q:'Que critique Xénophane chez Homère et Hésiode ?',o:['Leur style poétique','L\'anthropomorphisme et l\'immoralisme des dieux','Leur athéisme','Leur usage des nombres'],a:1,w:'Xénophane marque le début des lumières grecques en critiquant l\'image des dieux des mythes.'},
{id:'q093',s:'s6',t:'qcm',q:'Le dieu proposé par Xénophane est :',o:['Multiple et passionné','Unique, inengendré, omniscient, omnipotent, immobile','Fait de feu','Inexistant'],a:1,w:'Un dieu rationnel, cause du mouvement par la force de son esprit, parfait sur le plan moral.'},
{id:'q094',s:'s6',t:'qcm',q:'Pour Héraclite, l\'élément premier est :',o:['L\'eau','L\'air','Le feu','La terre'],a:2,w:'Le feu : tout est combustion perpétuelle. Héraclite est le penseur du mouvement.'},
{id:'q095',s:'s6',t:'qcm',q:'Selon Héraclite, comment la connaissance est-elle possible si tout change ?',o:['Par les sens','Par le logos du sage, qui capte la loi stable et rationnelle régissant le changement','Elle est impossible','Par les nombres'],a:1,w:'Héraclite est sceptique à l\'égard des sens, mais le logos (pensée, parole, ordre de l\'univers) peut capter la vérité.'},
{id:'q096',s:'s6',t:'qcm',q:'Par quel ouvrage connaît-on Parménide ?',o:['Plusieurs traités de physique','Un poème unique, De la nature','Des dialogues','Des fragments cités par Socrate'],a:1,w:'Un poème au ton mythique, mais qui est un traité d\'ontologie et de logique.'},
{id:'q097',s:'s6',t:'qcm',q:'Selon Parménide, quelle voie est impossible ?',o:['La vérité','Le non-être','Le semblant','L\'observation'],a:1,w:'Le réel n\'admet aucune contradiction : il est impossible de dire que le non-être est.'},
{id:'q098',s:'s6',t:'qcm',q:'Pour Parménide, l\'Être est :',o:['En perpétuel changement','Inengendré, impérissable, immobile, un, éternel','Fait d\'atomes','Une illusion'],a:1,w:'C\'est la voie de la vérité. Le devenir (le semblant) est l\'illusion.'},
{id:'q099',s:'s6',t:'qcm',q:'Quel est le principe premier de Démocrite ?',o:['Les atomes et le vide','Le feu','Le nombre','L\'Être'],a:0,w:'Il y a l\'être (les atomes) et le non-être (le vide).'},
{id:'q100',s:'s6',t:'qcm',q:'Les atomes de Démocrite diffèrent par :',o:['Leur couleur','Leur forme, leur ordre et leur grandeur','Leur qualité','Leur divinité'],a:1,w:'Ils sont indivisibles, insécables, en nombre infini, sans diversité qualitative.'},
{id:'q101',s:'s6',t:'qcm',q:'Selon Démocrite, qu\'est-ce qui est au fondement de l\'existence ?',o:['Dieu','Le hasard (pure mécanique)','L\'amour','Le logos'],a:1,w:'Pure mécanique : le hasard, et non dieu, est au fondement de l\'existence.'},
{id:'q102',s:'s6',t:'qcm',q:'Quel philosophe a pris Démocrite au sérieux tout en s\'y opposant ?',o:['Platon','Socrate','Aristote','Pythagore'],a:2,w:'On se moque de Démocrite à l\'époque; Aristote le prend au sérieux mais s\'oppose à lui.'},
{id:'q103',s:'s6',t:'qcm',q:'Quel présocratique est l\'exact opposé d\'Héraclite sur la question du changement ?',o:['Pythagore','Xénophane','Parménide','Démocrite'],a:2,w:'Héraclite : tout change. Parménide : l\'Être est immobile, le changement est une illusion.'},
{id:'q104',s:'s6',t:'vf',q:'Xénophane propose un dieu unique, inengendré et immobile.',a:true,w:'Vrai. Il est cause du mouvement par la force de son esprit.'},
{id:'q105',s:'s6',t:'vf',q:'Selon Parménide, l\'Être est en mouvement perpétuel.',a:false,w:'Faux. C\'est Héraclite qui pense que rien n\'est stable. Pour Parménide, l\'Être est immobile.'},
{id:'q106',s:'s6',t:'vf',q:'Démocrite place dieu au fondement de l\'existence.',a:false,w:'Faux. C\'est le hasard, pure mécanique.'},
{id:'q107',s:'s6',t:'vf',q:'Pythagore est décrit comme une figure quasi légendaire, chef d\'un culte religieux.',a:true,w:'Vrai : un mage, un prophète, un devin, chef d\'un culte qui vénère les nombres.'},
{id:'q108',s:'s6',t:'vf',q:'Héraclite fait entièrement confiance au témoignage des sens.',a:false,w:'Faux. Il est sceptique à l\'égard des sens, toujours relatifs, car ils perçoivent des objets en flux.'},
{id:'q109',s:'s6',t:'courte',q:'Donne le principe premier de Pythagore, Héraclite, Parménide et Démocrite.',m:'<ul><li><b>Pythagore</b> : le nombre.</li><li><b>Héraclite</b> : le feu (combustion perpétuelle).</li><li><b>Parménide</b> : l\'Être (un, immobile, éternel).</li><li><b>Démocrite</b> : les atomes et le vide.</li></ul><p>Bonus : Xénophane, un dieu unique et rationnel.</p>',k:['nombre','feu','Être','atomes','vide']},
{id:'q110',s:'s6',t:'courte',q:'Explique les trois voies de la connaissance selon Parménide.',m:'<ol><li><b>La vérité</b> : l\'Être est inengendré, impérissable, universel, immobile, éternel, un, continu.</li><li><b>Le non-être</b> : le réel n\'admet aucune contradiction; il est impossible de dire que le non-être est.</li><li><b>Le semblant (le devenir)</b> : l\'identité de l\'être et du non-être est une illusion.</li></ol>',k:['vérité','non-être','semblant','devenir','immobile','illusion']},
{id:'q111',s:'s6',t:'courte',q:'Explique la thèse d\'Héraclite sur le changement et sur la connaissance.',m:'<p>L\'élément premier est le feu : tout est combustion perpétuelle, rien n\'est stable (penseur du mouvement). Il est sceptique envers les sens, qui perçoivent des objets toujours en flux. La connaissance reste possible parce que le <b>logos</b> du sage (pensée, parole, ordre de l\'univers) capte la <b>loi stable et rationnelle qui régit le changement</b>.</p>',k:['feu','mouvement','rien n\'est stable','sens','logos','loi stable']},
{id:'q112',s:'s6',t:'courte',q:'Explique la position de Xénophane sur les dieux (critique, scepticisme, proposition).',m:'<p><b>Critique</b> : il rejette l\'image anthropomorphique et immorale des dieux d\'Homère et d\'Hésiode. <b>Scepticisme</b> : peut-on connaître la nature des dieux, vu l\'écart entre eux et nous, êtres imparfaits et finis ? <b>Proposition</b> : un dieu rationnel, unique, inengendré, omniscient, omnipotent, immobile, cause du mouvement par son esprit, parfait moralement.</p>',k:['anthropomorphisme','immoralisme','scepticisme','unique','immobile','rationnel']},
{id:'q113',s:'s6',t:'courte',q:'Décris l\'atomisme de Démocrite en trois points.',m:'<ol><li>Les atomes sont indivisibles, insécables, en nombre infini, sans diversité qualitative; ils diffèrent par la forme, l\'ordre et la grandeur.</li><li>Il y a l\'être (les atomes) et le non-être (le vide).</li><li>Pure mécanique : le hasard, et non dieu, est au fondement de l\'existence. Aristote le prend au sérieux mais s\'y oppose.</li></ol>',k:['indivisibles','infini','forme','ordre','grandeur','vide','hasard']},

// ---------------- s7 : doxa et logos
{id:'q120',s:'s7',t:'qcm',q:'La doxa est :',o:['Un discours rationnel visant l\'universel','Une croyance ou opinion non examinée, fondée sur l\'apparence, l\'habitude ou l\'autorité','La science','La loi de la cité'],a:1,w:'Elle ne repose pas sur une justification rationnelle universelle.'},
{id:'q121',s:'s7',t:'qcm',q:'Quelle paire est correcte ?',o:['Doxa = essence, logos = apparence','Doxa = persuasion, logos = justification','Doxa = universel, logos = relatif','Doxa = raison, logos = opinion'],a:1,w:'Doxa : opinion, apparence, persuasion, relatif. Logos : raison, essence, justification, universel.'},
{id:'q122',s:'s7',t:'qcm',q:'Qui a dit que l\'être humain est « l\'animal doué de logos » ?',o:['Platon','Aristote','Socrate','Héraclite'],a:1,w:'Aristote. La citation sur l\'opinion et la science est de Platon (La République, livre V).'},
{id:'q123',s:'s7',t:'qcm',q:'« L\'opinion se rapporte à ce qui devient et change, tandis que la science se rapporte à ce qui est. » Cette citation vient de :',o:['Aristote','Platon, La République, livre V','Hésiode','Protagoras'],a:1,w:'Platon, La République, livre V. Elle définit la doxa.'},
{id:'q124',s:'s7',t:'vf',q:'Le logos est un discours structuré par la raison, capable de se justifier et visant une validité universelle.',a:true,w:'Vrai, c\'est la définition du cours.'},
{id:'q125',s:'s7',t:'vf',q:'Les sophistes se situent du côté du logos et Socrate du côté de la doxa.',a:false,w:'Faux, c\'est l\'inverse : les sophistes travaillent l\'apparence, la persuasion et le relatif (doxa); Socrate cherche l\'essence, la justification et l\'universel (logos).'},
{id:'q126',s:'s7',t:'courte',q:'Définis la doxa et le logos, puis donne les quatre oppositions du tableau.',m:'<p><b>Doxa</b> : croyance ou opinion non examinée, fondée sur l\'apparence, l\'habitude ou l\'autorité, sans justification rationnelle universelle. <b>Logos</b> : discours structuré par la raison, capable de se justifier et visant une validité universelle.</p><p>Opinion / raison; apparence / essence; persuasion / justification; relatif / universel.</p>',k:['opinion','non examinée','raison','justifier','universel','apparence','essence','persuasion','relatif']},

// ---------------- s8 : démocratie athénienne
{id:'q130',s:'s8',t:'qcm',q:'Qui est surnommé « le père de la démocratie » ?',o:['Clisthène','Solon','Périclès','Socrate'],a:1,w:'Solon (vers 640 à 558 av. J.-C.), premier haut fonctionnaire à prendre en considération les revendications du peuple.'},
{id:'q131',s:'s8',t:'qcm',q:'Quelle réforme de Solon est la plus significative selon le cours ?',o:['La construction de l\'Acropole','La substitution de l\'aristocratie de fortune à l\'aristocratie de naissance','La création des dix tribus','L\'ostracisme'],a:1,w:'Elle donne à tout citoyen l\'opportunité de s\'enrichir et ouvre la porte à une réelle démocratie.'},
{id:'q132',s:'s8',t:'qcm',q:'Clisthène divise le territoire en :',o:['5 tribus','10 tribus','50 tribus','500 tribus'],a:1,w:'10 tribus mélangeant les couches socio-économiques, pour supprimer le privilège aristocratique.'},
{id:'q133',s:'s8',t:'qcm',q:'L\'ostracisme consiste à :',o:['Tirer au sort les juges','Expulser de la cité un citoyen devenu trop influent','Abolir les dettes des paysans','Élire un stratège'],a:1,w:'Mis en place par Clisthène pour éviter un basculement vers la tyrannie.'},
{id:'q134',s:'s8',t:'qcm',q:'Quelle instance vote toutes les lois et surveille les hauts magistrats ?',o:['Le Conseil du Roi','L\'Assemblée du peuple','Le tribunal populaire','Les sophistes'],a:1,w:'L\'Assemblée du peuple nomme et surveille les magistrats, vote les lois élaborées par le Conseil et administre la justice.'},
{id:'q135',s:'s8',t:'qcm',q:'Sur quoi les rois des cités-États fondaient-ils leur autorité ?',o:['Les lois écrites','Les rituels religieux','Le vote des citoyens','La richesse commerciale'],a:1,w:'La pensée mythique dominait; l\'alliance du religieux et du politique maintenait la cohésion sociale.'},
{id:'q136',s:'s8',t:'qcm',q:'Quelle classe a réclamé des lois écrites, marquant le passage de la justice divine à la justice humaine ?',o:['Les rois','Les prêtres','La classe commerçante enrichie par les échanges','Les esclaves'],a:2,w:'Elle remettait en question le pouvoir arbitraire de la classe gouvernante.'},
{id:'q137',s:'s8',t:'qcm',q:'Selon Platon, en quoi la démocratie dégénère-t-elle ?',o:['En oligarchie','En timocratie','En tyrannie','En aristocratie'],a:2,w:'Cycle : aristocratie, timocratie, oligarchie, démocratie, tyrannie. La démocratie dérive par excès de liberté.'},
{id:'q138',s:'s8',t:'qcm',q:'Quelle est la valeur dominante de l\'oligarchie selon Platon ?',o:['L\'honneur','La richesse','La liberté','La sagesse'],a:1,w:'Oligarchie : gouvernement des riches, valeur = richesse, dirigeant = élite économique, dérive = démocratie.'},
{id:'q139',s:'s8',t:'qcm',q:'Quel est le régime idéal selon Platon ?',o:['La démocratie','L\'aristocratie, gouvernement des meilleurs (philosophes)','La timocratie','La monarchie'],a:1,w:'Valeur : sagesse; dirigeant : philosophe-roi; problème : idéal difficile à maintenir.'},
{id:'q140',s:'s8',t:'qcm',q:'La démocratie athénienne était :',o:['Représentative','Directe','Monarchique','Oligarchique'],a:1,w:'Contrairement à nos démocraties représentatives, le peuple gouvernait directement.'},
{id:'q141',s:'s8',t:'qcm',q:'Combien de conseillers chaque tribu fournissait-elle au gouvernement, et comment étaient-ils choisis ?',o:['50, tirés au sort','50, élus','500, élus','10, tirés au sort'],a:0,w:'50 conseillers tirés au sort par tribu; 1 stratège élu annuellement; 500 juges par tribu tirés au sort.'},
{id:'q142',s:'s8',t:'qcm',q:'Quelle valeur les Athéniens plaçaient-ils au-dessus de tout ?',o:['La richesse','La liberté','L\'honneur militaire','La piété'],a:1,w:'Ils méprisaient le fait de se prosterner devant un maître autre que la loi.'},
{id:'q143',s:'s8',t:'qcm',q:'Comment la démocratie athénienne s\'est-elle dégradée à la fin du 5e siècle ?',o:['Par une invasion perse','Des hommes riches et cultivés ont poussé le peuple à des décrets contraires aux lois existantes, menant au désordre','Par le retour des rois','Par l\'abolition de l\'Assemblée'],a:1,w:'Décisions extravagantes à l\'encontre du bien commun; désordre total. Ces controverses nourrissent les débats sophistes contre Socrate et Platon.'},
{id:'q144',s:'s8',t:'vf',q:'La démocratie athénienne était représentative, comme la nôtre.',a:false,w:'Faux. C\'était une démocratie directe : le peuple gouvernait directement.'},
{id:'q145',s:'s8',t:'vf',q:'Le stratège était tiré au sort chaque année.',a:false,w:'Faux. Le stratège était élu annuellement par scrutin; ce sont les conseillers et les juges qui étaient tirés au sort.'},
{id:'q146',s:'s8',t:'vf',q:'Solon a libéré les esclaves d\'origine grecque.',a:true,w:'Vrai, avec l\'abolition des dettes des paysans et la substitution de l\'aristocratie de fortune à celle de naissance.'},
{id:'q147',s:'s8',t:'vf',q:'Pour Platon, la dérive de la timocratie est l\'oligarchie.',a:true,w:'Vrai : aristocratie → timocratie → oligarchie → démocratie → tyrannie.'},
{id:'q148',s:'s8',t:'vf',q:'Le tirage au sort servait à concentrer le pouvoir entre les mains des plus compétents.',a:false,w:'Faux. Il faisait circuler le pouvoir entre plusieurs citoyens, ce qui limitait les intrigues et la concentration du pouvoir.'},
{id:'q149',s:'s8',t:'courte',q:'Nomme les trois réformes de Solon et explique pourquoi la troisième est la plus significative.',m:'<ol><li>Abolition des dettes imposées par les riches propriétaires terriens aux paysans.</li><li>Libération des esclaves d\'origine grecque.</li><li>Substitution de l\'aristocratie de fortune à l\'aristocratie de naissance.</li></ol><p>La troisième donne à tout citoyen l\'opportunité de s\'enrichir et ouvre la porte à une réelle démocratie : plus de flexibilité entre les couches sociales, les nobles de sang ne sont plus seuls aux charges publiques.</p>',k:['dettes','esclaves','aristocratie de fortune','naissance','s\'enrichir']},
{id:'q150',s:'s8',t:'courte',q:'Décris le système mis en place par Clisthène.',m:'<p>Système décimal : le territoire est divisé en <b>10 tribus</b> mélangeant les couches socio-économiques. Gouvernement : <b>1 stratège</b> (général) élu annuellement par scrutin et <b>50 conseillers</b> tirés au sort par tribu. <b>Tribunal populaire</b> : 500 juges par tribu, tirés au sort. <b>Ostracisme</b> : expulsion des citoyens trop influents pour éviter la tyrannie.</p>',k:['10 tribus','stratège','élu','50 conseillers','tirés au sort','500 juges','ostracisme']},
{id:'q151',s:'s8',t:'courte',q:'Donne le cycle des régimes politiques selon Platon avec la valeur dominante de chacun.',m:'<p><b>Aristocratie</b> (sagesse) → <b>timocratie</b> (honneur) → <b>oligarchie</b> (richesse) → <b>démocratie</b> (liberté) → <b>tyrannie</b> (désir, pouvoir).</p>',k:['aristocratie','timocratie','oligarchie','démocratie','tyrannie','sagesse','honneur','richesse','liberté']},
{id:'q152',s:'s8',t:'courte',q:'Explique comment on est passé de la justice divine à la justice humaine dans les cités grecques.',m:'<p>Les rois fondaient leur autorité sur les rituels religieux. Avec l\'enrichissement, les riches propriétaires terriens (Conseil du Roi) ont instauré une aristocratie justifiée par une justice divine modifiée à leur avantage. Plus tard, la classe commerçante enrichie a contesté ce pouvoir arbitraire et réclamé des <b>lois écrites</b> : les lois ne sont plus immuables et divines, elles ont une origine historique. Des régimes plus modérés apparaissent, et à Athènes, la démocratie.</p>',k:['rituels religieux','propriétaires','aristocratie','classe commerçante','lois écrites','conventionnelle']},
{id:'q153',s:'s8',t:'courte',q:'Pourquoi la démocratie athénienne était-elle un contexte idéal pour les sophistes ?',m:'<p>Les décisions politiques y étaient débattues publiquement devant l\'Assemblée, où tout citoyen pouvait parler. Les jeunes riches aux ambitions politiques voulaient apprendre à persuader les foules par de beaux discours pour influencer le vote de la majorité. Les sophistes, maîtres dans l\'art de bien parler, vendaient exactement cela.</p>',k:['Assemblée','discours','persuader','jeunes riches','vote']},

// ---------------- s9 : sophistes
{id:'q160',s:'s9',t:'qcm',q:'Les sophistes étaient :',o:['Des prêtres','Des enseignants professionnels, itinérants et rémunérés','Des juges','Des philosophes de la nature'],a:1,w:'Trois mots : professionnels, itinérants, rémunérés.'},
{id:'q161',s:'s9',t:'qcm',q:'Pourquoi considère-t-on les sophistes comme les premiers humanistes ?',o:['Ils placent l\'humain et le langage au centre de leurs théories','Ils étudient la nature','Ils vénèrent les dieux','Ils refusent l\'argent'],a:0,w:'Au lieu de normes universelles, ils cherchent des normes pragmatiques centrées sur l\'humain.'},
{id:'q162',s:'s9',t:'qcm',q:'Quel était le but de l\'enseignement des sophistes ?',o:['Former des prêtres','Former des citoyens capables de réussir dans la vie publique (politique et tribunaux)','Découvrir le principe premier de la nature','Renverser la démocratie'],a:1,w:'Leur outil : l\'efficacité du discours. Persuader ou manipuler ?'},
{id:'q163',s:'s9',t:'vf',q:'Les sophistes étaient tous d\'accord sur ce qui est le plus utile pour la vie en société.',a:false,w:'Faux. Ils se divisent notamment en deux camps sur la justice : obéir à la loi (Protagoras) ou suivre la nature (loi du plus fort).'},
{id:'q164',s:'s9',t:'vf',q:'Les sophistes cherchaient des normes universelles.',a:false,w:'Faux. Ils se concentraient sur des normes pragmatiques. C\'est Socrate qui cherche l\'universel.'},
{id:'q165',s:'s9',t:'courte',q:'Qui sont les sophistes ? Donne trois caractéristiques et leur but.',m:'<p>Des enseignants <b>professionnels, itinérants et rémunérés</b>, apparus dans le contexte démocratique où les décisions sont débattues publiquement. Leur but : former des citoyens capables de réussir dans la vie publique (politique, tribunaux) grâce à l\'efficacité du discours. Ils placent l\'humain et le langage au centre et cherchent des normes pragmatiques : les premiers humanistes.</p>',k:['professionnels','itinérants','rémunérés','vie publique','discours','humanistes']},

// ---------------- s10 : Protagoras
{id:'q170',s:'s10',t:'qcm',q:'Selon la théorie de Protagoras, les humains sont passés :',o:['De la société à l\'état sauvage','D\'un état primitif égoïste à un contrat d\'entraide mutuelle','De la démocratie à la tyrannie','De la loi à la nature'],a:1,w:'Par un lent apprentissage, ils se libèrent de leurs instincts primitifs et égoïstes et obéissent aux lois qui garantissent sécurité et égalité.'},
{id:'q171',s:'s10',t:'qcm',q:'Pour Protagoras, sans respect de la convention, la vie humaine :',o:['S\'améliore','Régresse vers un état de désordre et de guerre perpétuelle','Reste stable','Devient divine'],a:1,w:'C\'est pourquoi il loue les mérites des lois et défend la supériorité de la convention.'},
{id:'q172',s:'s10',t:'qcm',q:'Sur la question des dieux, Protagoras était :',o:['Athée','Agnostique','Polythéiste convaincu','Monothéiste'],a:1,w:'Il remettait en question la possibilité de confirmer ou d\'infirmer leur existence sur la base de nos sens.'},
{id:'q173',s:'s10',t:'qcm',q:'« La science est la sensation » signifie :',o:['Le réel et le vrai dépendent de ce qui apparaît à nos sens et de la manière dont nous l\'organisons en discours','La science utilise des instruments','Les sens trompent toujours','La science vient des dieux'],a:0,w:'Deuxième prémisse du subjectivisme de Protagoras.'},
{id:'q174',s:'s10',t:'qcm',q:'Pour Protagoras, « justice » et « légalité » sont :',o:['Opposées','Synonymes','Sans rapport','Divines'],a:1,w:'Conséquence 7 : la justice, c\'est la loi que nous nous donnons dans une convention. Socrate distingue au contraire le juste du légal.'},
{id:'q175',s:'s10',t:'qcm',q:'Selon Protagoras, une loi établie par convention est juste tant que :',o:['Les dieux l\'approuvent','La majorité la croit telle','Le plus fort la respecte','Socrate l\'accepte'],a:1,w:'Conséquence 8. Il n\'y a pas de justice universelle supérieure à la convention.'},
{id:'q176',s:'s10',t:'qcm',q:'Quelle est la conclusion finale (conséquence 9) de Protagoras ?',o:['Il faut désobéir aux lois quand on ne risque rien','Il faut respecter la convention, qui est le plus grand bien','Il faut suivre la nature','Il faut fuir la cité'],a:1,w:'Protagoras est relativiste, mais il défend les lois. Ce sont les autres sophistes qui prônent la loi du plus fort.'},
{id:'q177',s:'s10',t:'qcm',q:'Que garantissent les lois selon Protagoras ?',o:['La richesse','La sécurité et l\'égalité','La gloire','La vérité'],a:1,w:'Le désir de quitter l\'état brutal motive l\'obéissance aux lois qui garantissent sécurité et égalité.'},
{id:'q178',s:'s10',t:'vf',q:'Protagoras pense qu\'il faut désobéir aux lois quand on ne risque pas de se faire prendre.',a:false,w:'Faux. C\'est la position des sophistes de la loi du plus fort (Antiphon, Calliclès). Protagoras dit qu\'il faut respecter la convention.'},
{id:'q179',s:'s10',t:'vf',q:'Selon Protagoras, il n\'existe pas de justice universelle supérieure à la convention.',a:true,w:'Vrai, conséquence 6 du relativisme.'},
{id:'q180',s:'s10',t:'vf',q:'Pour Protagoras, la connaissance du bien peut être fondée sur des lois naturelles objectives.',a:false,w:'Faux. Conséquence 4 : elle ne peut pas l\'être, car tout est subjectif.'},
{id:'q181',s:'s10',t:'courte',q:'Explique la théorie du développement des sociétés humaines de Protagoras.',m:'<p>À l\'origine, les humains vivaient dans un <b>état primitif sauvage</b>, suivant leurs instincts égoïstes et querelleurs. Par un <b>lent apprentissage</b>, ils s\'en sont libérés pour passer à un <b>contrat d\'entraide mutuelle</b>. Le désir de quitter cet état brutal les a poussés à obéir aux lois qui garantissent <b>sécurité et égalité</b>. La société enseigne les vertus et l\'éducation fait obéir à la convention. Protagoras défend donc la <b>supériorité de la convention</b> pour éviter la tyrannie des puissants.</p>',k:['état primitif','instincts','contrat','entraide','sécurité','égalité','convention','éducation']},
{id:'q182',s:'s10',t:'courte',q:'Donne les trois prémisses du subjectivisme de Protagoras.',m:'<ol><li>La nature n\'offre rien de stable à nos perceptions : les contradictions perpétuelles des apparences sont le fond sur lequel l\'humain élabore la réalité.</li><li>La science est la sensation : le réel et le vrai dépendent de la manière dont nous organisons en discours ce qui apparaît à nos sens.</li><li>Tout est subjectif : les choses ne sont que ce que nous disons qu\'elles sont.</li></ol>',k:['rien de stable','perceptions','sensation','discours','subjectif']},
{id:'q183',s:'s10',t:'courte',q:'Explique le relativisme de la vérité, de la justice et de la moralité chez les sophistes.',m:'<ul><li><b>Vérité</b> : le vrai dépend des perceptions et du discours de chacun (la science est la sensation, tout est subjectif).</li><li><b>Justice</b> : elle n\'a pas de qualités objectives; justice = légalité = ce que la majorité décide par convention.</li><li><b>Moralité</b> : le bien n\'est pas objectif; en pratique, le bien est remplacé par l\'utile et la vérité par la vraisemblance.</li></ul>',k:['subjectif','légalité','majorité','convention','utile','vraisemblance']},
{id:'q184',s:'s10',t:'courte',q:'Nomme quatre des six conséquences du subjectivisme de Protagoras.',m:'<ol start="4"><li>La connaissance du bien et du juste ne peut être fondée sur des lois naturelles objectives.</li><li>La justice n\'a pas de qualités objectives : elle dépend des décisions humaines.</li><li>Il n\'y a pas de justice universelle supérieure à la convention.</li><li>« Justice » et « légalité » sont synonymes.</li><li>La loi conventionnelle est juste tant que la majorité la croit telle.</li><li>Il faut respecter la convention, le plus grand bien.</li></ol>',k:['objectives','décisions humaines','universelle','légalité','majorité','respecter la convention']},

// ---------------- s11 : pragmatisme
{id:'q190',s:'s11',t:'qcm',q:'Dans le pragmatisme des sophistes, le bien est remplacé par ___ et la vérité par ___.',o:['L\'utile / la vraisemblance','Le beau / la science','La loi / le mythe','La force / le hasard'],a:0,w:'La formule à retenir : le bien est remplacé par l\'utile, et la vérité par la vraisemblance.'},
{id:'q191',s:'s11',t:'qcm',q:'Le discours double consiste à :',o:['Parler deux langues','Louer et blâmer chacune des deux positions opposées d\'un même problème','Répéter deux fois son argument','Dialoguer à deux'],a:1,w:'Les élèves apprennent à déjouer les arguments contraires; la position la plus faible peut l\'emporter.'},
{id:'q192',s:'s11',t:'qcm',q:'Que doit posséder l\'homme d\'État selon Protagoras ?',o:['La richesse','L\'art de la rhétorique','La force militaire','La piété'],a:1,w:'Pour reconnaître ce qui est le plus avantageux et faire adopter les opinions les plus utiles à la vie commune.'},
{id:'q193',s:'s11',t:'qcm',q:'Selon le cours, que disait-on de l\'enseignement de Protagoras ?',o:['Qu\'il enseignait la vérité universelle','Qu\'il enseignait l\'art de faire que l\'argument le plus faible l\'emporte sur le fort','Qu\'il enseignait la physique','Qu\'il enseignait gratuitement'],a:1,w:'Cette même formule sera une accusation contre Socrate, qui répondra qu\'on le confond avec les sophistes.'},
{id:'q194',s:'s11',t:'qcm',q:'Quel problème le pragmatisme de Protagoras veut-il résoudre ?',o:['Le manque de dieux','Si chacun s\'invente sa propre justice, on obtient une guerre continuelle d\'intérêts contradictoires','L\'absence d\'écriture','La pauvreté des paysans'],a:1,w:'D\'où la nécessité pour l\'homme d\'État de faire adopter par la rhétorique les opinions les plus utiles.'},
{id:'q195',s:'s11',t:'vf',q:'Pour Protagoras, les opinions que l\'homme d\'État fait adopter peuvent être des croyances ou des fictions qui maintiennent la cohésion sociale.',a:true,w:'Vrai. Ce qui compte, c\'est l\'utilité pour la vie commune, pas la vérité.'},
{id:'q196',s:'s11',t:'vf',q:'Selon le pragmatisme, la sagesse consiste à découvrir la vérité universelle.',a:false,w:'Faux. Pour Protagoras, la sagesse est la capacité d\'influencer les foules et de rallier la majorité autour des opinions qui conviennent au contexte.'},
{id:'q197',s:'s11',t:'courte',q:'Explique la formule « le bien est remplacé par l\'utile et la vérité par la vraisemblance ».',m:'<p>Chez les sophistes, l\'homme d\'État ne cherche pas ce qui est bien en soi, mais ce qui est le plus <b>utile</b> à la vie commune (des normes pragmatiques). Et il ne cherche pas la vérité, mais ce qui paraît vrai à la foule, la <b>vraisemblance</b>, qu\'il fait adopter par des discours persuasifs. Le critère n\'est plus le vrai et le bien, mais ce qui fonctionne et rallie la majorité.</p>',k:['utile','vraisemblance','persuasion','majorité','pragmatique']},
{id:'q198',s:'s11',t:'courte',q:'Qu\'est-ce que le discours double et quel était son effet ?',m:'<p>Technique de Protagoras qui consiste à <b>louer et blâmer chacune des deux positions opposées</b> d\'un même problème. Les élèves développaient l\'habileté de déjouer les arguments contraires, si bien que la position qui paraissait la plus faible pouvait l\'emporter. On disait que Protagoras enseignait l\'art de faire que l\'argument le plus faible l\'emporte sur le fort.</p>',k:['louer','blâmer','deux positions','le plus faible','l\'emporte']},

// ---------------- s12 : loi du plus fort
{id:'q200',s:'s12',t:'qcm',q:'Qui affirme que la loi n\'est qu\'une invention de la majorité, composée de faibles, pour empêcher les plus forts de les dominer ?',o:['Protagoras','Antiphon','Socrate','Solon'],a:1,w:'Antiphon, sophiste.'},
{id:'q201',s:'s12',t:'qcm',q:'Dans La République de Platon, qui soutient que la justice véritable est la loi du plus fort ?',o:['Glaucon','Thrasymaque','Calliclès','Protagoras'],a:1,w:'Thrasymaque : le plus fort commande et établit les lois dans son propre intérêt; le faible obéit par peur des représailles.'},
{id:'q202',s:'s12',t:'qcm',q:'L\'histoire du berger au service du roi de Lydie est utilisée par :',o:['Thrasymaque','Glaucon','Antiphon','Xénophane'],a:1,w:'Glaucon : avec un tel pouvoir, personne ne résisterait à commettre le mal dans son intérêt.'},
{id:'q203',s:'s12',t:'qcm',q:'Qui affirme que « l\'homme le plus juste est le tyran le plus cruel » ?',o:['Calliclès','Protagoras','Socrate','Platon'],a:0,w:'Calliclès, riche aristocrate, exemple de l\'immoralité issue de l\'enseignement sophistique.'},
{id:'q204',s:'s12',t:'qcm',q:'Sur quelle question les sophistes se divisent-ils en deux camps ?',o:['La vérité','La justice humaine : obéir à la loi ou suivre la nature','L\'existence des dieux','Le prix de leurs cours'],a:1,w:'Ils partagent une vision relative de la vérité, mais Protagoras défend la loi alors qu\'Antiphon, Thrasymaque, Glaucon et Calliclès défendent la nature.'},
{id:'q205',s:'s12',t:'qcm',q:'Selon Thrasymaque, pourquoi le faible obéit-il à la loi ?',o:['Par vertu','Uniquement pour éviter des représailles','Par amour de la cité','Parce que la majorité l\'a votée'],a:1,w:'Et plus le chef est cruel, plus la foule se soumet et loue son tyran comme un bienfaiteur.'},
{id:'q206',s:'s12',t:'qcm',q:'Quel argument justifie la désobéissance aux lois chez les sophistes de la loi du plus fort ?',o:['Les lois sont divines','Si la loi n\'est que convention humaine, elle est artificielle par rapport à la nature','Les lois sont trop nombreuses','Les lois sont écrites'],a:1,w:'Il est donc justifié de désobéir chaque fois qu\'on ne risque pas de se faire prendre.'},
{id:'q207',s:'s12',t:'qcm',q:'Selon le cours, qu\'est devenu l\'éloge de la démocratie au sein de la sophistique ?',o:['Un éloge de la science','Un éloge de la tyrannie et de l\'égoïsme','Un éloge de la religion','Un éloge de Socrate'],a:1,w:'Le relativisme de Protagoras, interprété par ses auditeurs, a mené à des conséquences bien différentes de son but noble.'},
{id:'q208',s:'s12',t:'vf',q:'Pour Thrasymaque, le faible obéit uniquement pour éviter des représailles.',a:true,w:'Vrai.'},
{id:'q209',s:'s12',t:'vf',q:'Selon Glaucon, le respect de la loi est volontaire et naturel.',a:false,w:'Faux. Le respect de la loi n\'est jamais volontaire; la loi est un obstacle à la réalisation de la nature humaine.'},
{id:'q210',s:'s12',t:'vf',q:'Calliclès soutient que les plus forts ont le devoir de mépriser la loi conventionnelle.',a:true,w:'Vrai : ils doivent suivre la loi de la nature, qui dicte d\'user de tous les moyens pour dominer.'},
{id:'q211',s:'s12',t:'vf',q:'Antiphon, Thrasymaque et Glaucon rejettent le relativisme de la vérité.',a:false,w:'Faux. Tous les sophistes partagent une vision relative et subjective de la vérité; ils ne se divisent que sur la justice.'},
{id:'q212',s:'s12',t:'courte',q:'Explique la position d\'Antiphon, de Thrasymaque, de Glaucon et de Calliclès (une phrase chacun).',m:'<ul><li><b>Antiphon</b> : la loi est une invention de la majorité de faibles et de vauriens pour empêcher les forts de les dominer.</li><li><b>Thrasymaque</b> : la justice véritable est la loi du plus fort; le plus fort établit les lois dans son intérêt, le faible obéit par peur des représailles.</li><li><b>Glaucon</b> : les humains suivent leur nature égoïste; avec le pouvoir du berger de Lydie, personne ne resterait juste; le respect de la loi n\'est jamais volontaire.</li><li><b>Calliclès</b> : les plus forts ont le devoir de mépriser la loi et de suivre la nature; l\'homme le plus juste est le tyran le plus cruel.</li></ul>',k:['faibles','plus fort','intérêt','représailles','berger','Lydie','tyran']},
{id:'q213',s:'s12',t:'courte',q:'Quel est le point commun et la différence entre Protagoras et les sophistes de la loi du plus fort ?',m:'<p><b>Point commun</b> : la même théorie du développement des sociétés (nature contre loi) et une vision relative et subjective de la vérité. <b>Différence</b> : Protagoras conclut qu\'il faut obéir à la loi, qui garantit une justice égale pour tous; les autres (Antiphon, Thrasymaque, Glaucon, Calliclès) concluent que la loi est artificielle, qu\'elle freine injustement la nature humaine, et qu\'il faut suivre la nature, c\'est-à-dire la loi du plus fort.</p>',k:['nature','loi','relative','obéir','artificielle','plus fort']},
{id:'q214',s:'s12',t:'courte',q:'Pourquoi la loi devient-elle « une affaire de stratégie et de calcul » entre les mains des élèves des sophistes ?',m:'<p>Parce que l\'enseignement des sophistes visait seulement à outiller les élèves dans l\'art de bien argumenter. Les élèves pouvaient donc décider eux-mêmes de l\'usage de ce savoir : l\'intérêt personnel ou le bien commun. Rien dans la méthode ne les obligeait à choisir le bien commun; la loi devenait un outil qu\'on respecte ou contourne selon son intérêt.</p>',k:['argumenter','intérêt personnel','bien commun','usage']},

// ---------------- s13 : Socrate
{id:'q220',s:'s13',t:'qcm',q:'De quoi Socrate se soucie-t-il avant tout ?',o:['De la nature','De la vérité dans le domaine moral','De la richesse','De la rhétorique'],a:1,w:'Il voit dans l\'enseignement des sophistes une pratique qui entraîne la désobéissance aux lois et la dégradation des mœurs.'},
{id:'q221',s:'s13',t:'qcm',q:'Contrairement aux sophistes, Socrate :',o:['Vend un savoir','Promet le succès politique','Donne des recettes parfaites','Questionne'],a:3,w:'Il ne vend pas un savoir, ne promet pas le succès politique, ne donne pas de recettes : il questionne.'},
{id:'q222',s:'s13',t:'qcm',q:'« La vie sans examen ne vaut pas la peine d\'être vécue. » Cette citation vient de :',o:['Platon, L\'Apologie de Socrate','Platon, Théétète','Aristote','Laramée'],a:0,w:'L\'Apologie de Socrate, le récit du procès.'},
{id:'q223',s:'s13',t:'qcm',q:'Que suppose Socrate en rejetant le relativisme ?',o:['Que la vérité dépend de chacun','Qu\'il existe des définitions universelles, que les concepts ont une essence et que le bien n\'est pas arbitraire','Que les dieux décident du bien','Que la majorité a toujours raison'],a:1,w:'Trois suppositions : définitions universelles, essence des concepts, bien non arbitraire.'},
{id:'q224',s:'s13',t:'qcm',q:'Qu\'est-ce que l\'« ignorance qui s\'ignore » ?',o:['Ne rien savoir du tout','Croire savoir ce qu\'on ne sait pas','Savoir qu\'on ne sait pas','Refuser d\'apprendre'],a:1,w:'C\'est la prétention du savoir. L\'ignorance simple (savoir qu\'on ne sait pas) est la posture philosophique que privilégie Socrate.'},
{id:'q225',s:'s13',t:'qcm',q:'Par quoi commence la philosophie selon Socrate ?',o:['Par l\'observation de la nature','Par la conscience de son ignorance','Par la lecture des poètes','Par le succès politique'],a:1,w:'« La philosophie commence par la conscience de son ignorance. »'},
{id:'q226',s:'s13',t:'qcm',q:'Que dénonce Socrate chez ses concitoyens ?',o:['Le manque de richesse','La prétention du savoir et le conformisme irréfléchi','L\'absence de dieux','Le refus de voter'],a:1,w:'Comme ceux qui prônent la loi du plus fort, la recherche des plaisirs ou l\'accumulation des richesses.'},
{id:'q227',s:'s13',t:'qcm',q:'Où Socrate passe-t-il beaucoup de temps et pourquoi ?',o:['Au temple, pour prier','Sur les places publiques, pour discuter avec des gens de toutes les classes sociales','Dans une école, pour enseigner contre paiement','À l\'Assemblée, pour proposer des lois'],a:1,w:'Il encourage les gens à prendre soin de leur vie intérieure et de leur âme.'},
{id:'q228',s:'s13',t:'vf',q:'Socrate se faisait payer pour son enseignement.',a:false,w:'Faux. Il ne vend pas un savoir; au procès, il répond que la vertu ne peut être troquée contre de l\'argent.'},
{id:'q229',s:'s13',t:'vf',q:'Socrate rejette le relativisme des sophistes.',a:true,w:'Vrai : il existe des définitions universelles, les concepts ont une essence, le bien n\'est pas arbitraire.'},
{id:'q230',s:'s13',t:'vf',q:'Socrate a vécu et travaillé pendant les années phares de la démocratie athénienne.',a:true,w:'Vrai (470 à 399 av. J.-C.).'},
{id:'q231',s:'s13',t:'courte',q:'Distingue l\'ignorance simple et l\'ignorance qui s\'ignore. Laquelle Socrate privilégie-t-il ?',m:'<p><b>Ignorance simple</b> : je ne sais pas et je sais que je ne sais pas. <b>Ignorance qui s\'ignore</b> : je crois savoir ce que je ne sais pas (la prétention du savoir). Socrate privilégie l\'ignorance simple : « La philosophie commence par la conscience de son ignorance. » Citation : « Je suis plus sage que cet homme; car il croit savoir ce qu\'il ne sait pas, tandis que moi, si je ne sais pas, je ne crois pas savoir. »</p>',k:['sais que je ne sais pas','croit savoir','conscience de son ignorance','plus sage']},
{id:'q232',s:'s13',t:'courte',q:'En quoi l\'approche de Socrate diffère-t-elle de celle des sophistes ? Donne quatre points.',m:'<p>Il ne vend pas un savoir; il ne promet pas le succès politique; il ne donne pas de recettes parfaites; il questionne. De plus, il rejette le relativisme : il existe des définitions universelles, les concepts ont une essence, le bien n\'est pas arbitraire.</p>',k:['ne vend pas','succès politique','recettes','questionne','universelles','essence']},

// ---------------- s14 : méthodes socratiques
{id:'q240',s:'s14',t:'qcm',q:'Quel est l\'ordre des quatre étapes de la réfutation (elenchos) ?',o:['Contradiction, définition, acceptation, questionnement','Définition proposée, acceptation provisoire, questionnement, contradiction révélée','Questionnement, définition, contradiction, acceptation','Acceptation, contradiction, définition, questionnement'],a:1,w:'Définition proposée → acceptation provisoire → questionnement → contradiction révélée.'},
{id:'q241',s:'s14',t:'qcm',q:'La maïeutique est comparée à l\'art :',o:['Des médecins','Des sages-femmes','Des sculpteurs','Des orateurs'],a:1,w:'« Mon art est semblable à celui des sages-femmes; il consiste à examiner si la pensée enfante quelque chose de viable. » (Théétète)'},
{id:'q242',s:'s14',t:'qcm',q:'Que signifie le mot grec « aporia » ?',o:['Accouchement','Impasse, difficulté insurmontable, absence de passage','Réfutation','Persuasion'],a:1,w:'L\'aporie est le moment où l\'interlocuteur réalise qu\'il ne sait plus ce qu\'il croyait savoir.'},
{id:'q243',s:'s14',t:'qcm',q:'Dans la discussion réfutative, combien d\'interlocuteurs ont des rôles bien précis ?',o:['Un seul','Deux : l\'un questionne, l\'autre défend sa position','Trois','Tous les participants'],a:1,w:'Le premier questionne pour mettre à l\'épreuve les croyances; le deuxième défend le mieux possible sa position.'},
{id:'q244',s:'s14',t:'qcm',q:'À quoi vise l\'aporie ?',o:['À gagner le débat','À détruire l\'illusion du savoir et à amorcer une réflexion critique et prudente','À humilier l\'adversaire','À prouver l\'existence des dieux'],a:1,w:'Elle est le passage obligé vers une vraie recherche.'},
{id:'q245',s:'s14',t:'qcm',q:'Quelle méthode fait émerger la vérité chez l\'interlocuteur lui-même ?',o:['L\'elenchos','La maïeutique','L\'aporie','Le discours double'],a:1,w:'La vérité émerge du dialogue rationnel; Socrate aide à accoucher.'},
{id:'q246',s:'s14',t:'qcm',q:'« Ce n\'est pas moi qui réfute, mais la vérité qui apparaît par nos paroles. » Cette citation illustre :',o:['La maïeutique','La réfutation (elenchos)','Le pragmatisme','La loi du plus fort'],a:1,w:'C\'est la citation associée à l\'elenchos dans le cours.'},
{id:'q247',s:'s14',t:'vf',q:'La maïeutique vise à faire émerger la vérité chez l\'interlocuteur lui-même.',a:true,w:'Vrai.'},
{id:'q248',s:'s14',t:'vf',q:'L\'aporie est la conclusion positive d\'un dialogue, où l\'on obtient enfin une bonne définition.',a:false,w:'Faux. L\'aporie est une impasse : l\'interlocuteur ne sait plus ce qu\'il croyait savoir.'},
{id:'q249',s:'s14',t:'vf',q:'Dans l\'elenchos, Socrate rejette immédiatement la définition proposée.',a:false,w:'Faux. Il l\'accepte provisoirement, puis questionne jusqu\'à révéler une contradiction.'},
{id:'q250',s:'s14',t:'courte',q:'Explique les trois méthodes socratiques : elenchos, maïeutique, aporie.',m:'<ul><li><b>Elenchos (réfutation)</b> : définition proposée, acceptation provisoire, questionnement, contradiction révélée. « Ce n\'est pas moi qui réfute, mais la vérité qui apparaît par nos paroles. »</li><li><b>Maïeutique</b> : faire émerger la vérité chez l\'interlocuteur lui-même, comme une sage-femme fait accoucher; la vérité émerge du dialogue rationnel.</li><li><b>Aporie</b> : impasse; moment où l\'interlocuteur réalise que sa définition mène à une contradiction et qu\'il ne sait plus ce qu\'il croyait savoir. Elle détruit l\'illusion du savoir.</li></ul>',k:['réfutation','définition','acceptation provisoire','contradiction','sages-femmes','émerger','impasse','illusion du savoir']},
{id:'q251',s:'s14',t:'courte',q:'Décris la discussion réfutative et le rôle de chaque interlocuteur.',m:'<p>Une discussion qui peut inclure plusieurs participants, mais où seuls <b>deux interlocuteurs</b> ont des rôles précis : le premier <b>questionne</b> pour mettre à l\'épreuve les croyances; le deuxième <b>défend</b> le mieux possible sa position sur une question précise. Elle fait appel à une ou plusieurs méthodes socratiques (elenchos, maïeutique, aporie) pour découvrir la vérité.</p>',k:['deux interlocuteurs','questionne','défend','croyances']},

// ---------------- s15 : Euthyphron
{id:'q260',s:'s15',t:'qcm',q:'Quelle est la question centrale du dialogue d\'Euthyphron ?',o:['Qu\'est-ce que la justice ?','Qu\'est-ce que la piété ?','Qu\'est-ce que le courage ?','Qu\'est-ce que la beauté ?'],a:1,w:'Socrate cherche une définition universelle de la piété, pas des exemples.'},
{id:'q261',s:'s15',t:'qcm',q:'Où et quand Socrate rencontre-t-il Euthyphron ?',o:['À l\'agora, après son acquittement','Devant le tribunal d\'Athènes, peu avant son procès','En prison, après sa condamnation','Au temple, pendant un sacrifice'],a:1,w:'Socrate est accusé d\'impiété et de corruption de la jeunesse.'},
{id:'q262',s:'s15',t:'qcm',q:'Quel est le dilemme formulé par Socrate ?',o:['Faut-il obéir à son père ou aux dieux ?','Le pieux est-il aimé des dieux parce qu\'il est pieux, ou pieux parce que les dieux l\'aiment ?','Faut-il fuir ou mourir ?','La loi ou la nature ?'],a:1,w:'Si aimé parce que pieux, la piété existe indépendamment des dieux; si pieux parce qu\'aimé, la piété est arbitraire.'},
{id:'q263',s:'s15',t:'qcm',q:'Pourquoi Socrate rejette-t-il la définition « le pieux est ce qui plaît aux dieux » ?',o:['Parce que les dieux n\'existent pas','Parce que les dieux sont en désaccord entre eux : une même chose serait à la fois pieuse et impie','Parce que c\'est trop long','Parce qu\'Euthyphron n\'est pas prêtre'],a:1,w:'Selon les mythes, les dieux se querellent; la définition mène à une contradiction.'},
{id:'q264',s:'s15',t:'qcm',q:'Pourquoi Socrate rejette-t-il la première définition d\'Euthyphron (« la piété, c\'est ce que je fais : poursuivre le coupable ») ?',o:['Parce qu\'elle est fausse','Parce que c\'est un exemple, pas une définition universelle','Parce qu\'elle est impie','Parce que Zeus l\'interdit'],a:1,w:'Socrate veut la forme unique qui rend pieuses toutes les actions pieuses.'},
{id:'q265',s:'s15',t:'qcm',q:'Pourquoi Euthyphron est-il au tribunal ?',o:['Il est accusé d\'impiété','Il vient accuser son propre père de meurtre','Il est juge','Il défend Socrate'],a:1,w:'Il est certain que poursuivre son père est pieux, ce qui pousse Socrate à lui demander ce qu\'est la piété.'},
{id:'q266',s:'s15',t:'qcm',q:'Le dialogue d\'Euthyphron se termine :',o:['Par une définition satisfaisante de la piété','En aporie : Euthyphron s\'en va sans avoir défini la piété','Par la condamnation d\'Euthyphron','Par une réconciliation avec le père'],a:1,w:'Euthyphron illustre l\'ignorance qui s\'ignore.'},
{id:'q267',s:'s15',t:'vf',q:'Le dialogue d\'Euthyphron aboutit à une définition claire de la piété.',a:false,w:'Faux. Il se termine en aporie.'},
{id:'q268',s:'s15',t:'vf',q:'Le dilemme d\'Euthyphron peut se généraliser à toute autorité : une action est-elle bonne parce qu\'une autorité l\'approuve, ou pour des raisons indépendantes ?',a:true,w:'Vrai, c\'est la question que pose la diapo.'},
{id:'q269',s:'s15',t:'courte',q:'Donne deux définitions de la piété proposées par Euthyphron et explique pourquoi Socrate les rejette.',m:'<ol><li>« La piété, c\'est ce que je fais : poursuivre le coupable, même mon père. » Rejetée : c\'est un <b>exemple</b>, pas une définition universelle.</li><li>« Le pieux est ce qui est <b>cher aux dieux</b>. » Rejetée : les dieux sont en <b>désaccord</b>, donc une même action serait pieuse et impie.</li><li>« Le pieux est ce que <b>tous</b> les dieux aiment. » Rejetée par le dilemme : être aimé des dieux est une qualité qui accompagne la piété, pas son essence.</li><li>« La piété est la partie de la justice qui concerne le <b>soin des dieux</b>. » Rejetée : ce soin se réduit à un commerce (prières, sacrifices), ce qui ramène à « ce qui plaît aux dieux » : on tourne en rond.</li></ol>',k:['exemple','cher aux dieux','désaccord','tous les dieux','soin','commerce']},
{id:'q270',s:'s15',t:'courte',q:'Formule le dilemme d\'Euthyphron et explique ses deux branches.',m:'<p><b>Le pieux est-il aimé des dieux parce qu\'il est pieux, ou est-il pieux parce que les dieux l\'aiment ?</b></p><ul><li>Si les dieux l\'aiment parce qu\'il est pieux : la piété existe indépendamment des dieux, leur amour n\'en est qu\'une conséquence, et il reste à la définir.</li><li>S\'il est pieux parce que les dieux l\'aiment : la piété est arbitraire, elle dépend d\'un caprice, n\'importe quoi pourrait devenir pieux.</li></ul>',k:['parce qu\'il est pieux','parce que les dieux l\'aiment','indépendamment','arbitraire']},

// ---------------- s16 : vertu-science
{id:'q280',s:'s16',t:'qcm',q:'La vertu-science établit un lien étroit entre :',o:['La force et la loi','L\'action moralement bonne et la connaissance rationnelle','La richesse et le bonheur','Les dieux et les lois'],a:1,w:'Pour posséder la vertu, il faut une connaissance rationnelle du bien, ni relative à chacun, ni basée sur l\'opinion de la majorité.'},
{id:'q281',s:'s16',t:'qcm',q:'Selon Socrate, pourquoi faisons-nous le mal ?',o:['Par nature','Parce que nous avons de la difficulté à connaître le bien','Par plaisir','Parce que les dieux le veulent'],a:1,w:'Si notre jugement était sain, aucune passion ne ferait obstacle à la volonté d\'agir vertueusement, car la vertu apporte le bonheur.'},
{id:'q282',s:'s16',t:'qcm',q:'Où se trouve la connaissance du bien selon Socrate ?',o:['Dans les livres','Dans la profondeur de notre âme : le bien est inné','Chez les sophistes','Dans les lois de la cité'],a:1,w:'Ce n\'est pas un savoir théorique ou académique. Chacun a naturellement en lui le sens du bien.'},
{id:'q283',s:'s16',t:'qcm',q:'Qu\'est-ce qui nous empêche d\'accéder à la connaissance du bien ?',o:['Notre corps','Les opinions, les fausses connaissances et les préjugés acquis par manque de réflexion','Les dieux','Le manque d\'argent'],a:1,w:'D\'où la nécessité de désapprendre ce qu\'on croit savoir et de déconstruire le pseudo-savoir.'},
{id:'q284',s:'s16',t:'qcm',q:'Que signifie atteindre le « degré zéro du savoir » ?',o:['Ne plus rien apprendre','Reconnaître que notre savoir était une opinion, pour que l\'âme cherche un savoir plus profond et vrai','Échouer à l\'examen','Oublier les dieux'],a:1,w:'C\'est ce que produisent les discussions réfutatives.'},
{id:'q285',s:'s16',t:'qcm',q:'À quoi le philosophe doit-il attacher plus d\'importance selon Socrate ?',o:['À son corps','À son âme (justice et piété plutôt que biens matériels)','À sa réputation','À sa richesse'],a:1,w:'La tâche du philosophe : faire prendre conscience aux autres que le bien est en eux.'},
{id:'q286',s:'s16',t:'vf',q:'Pour Socrate, la vertu apporte le bonheur.',a:true,w:'Vrai. C\'est pourquoi un jugement sain suffirait à agir vertueusement.'},
{id:'q287',s:'s16',t:'vf',q:'La connaissance du bien, chez Socrate, est un savoir théorique et académique.',a:false,w:'Faux. Elle se découvre dans la profondeur de notre âme; le bien est inné.'},
{id:'q288',s:'s16',t:'vf',q:'Socrate admet plusieurs standards pour juger nos actions, selon les cultures.',a:false,w:'Faux. Il n\'y a qu\'une seule vérité et un seul standard : il s\'oppose au relativisme des sophistes.'},
{id:'q289',s:'s16',t:'courte',q:'Explique la vertu-science de Socrate.',m:'<p>La vertu-science est le <b>rapport étroit entre l\'action moralement bonne et la connaissance rationnelle</b>. Pour être vertueux, il faut une connaissance rationnelle du bien, ni relative à chacun, ni fondée sur l\'opinion de la majorité, comme un art exige un savoir. Le bien est <b>inné</b>, dans la profondeur de l\'âme, mais les opinions et préjugés nous en cachent l\'accès : il faut désapprendre le pseudo-savoir (elenchos, aporie) pour atteindre le degré zéro du savoir, puis chercher la vérité. Conséquence : <b>le mal vient de l\'ignorance</b>; qui connaît vraiment le bien agit bien, car la vertu apporte le bonheur.</p>',k:['connaissance rationnelle','bien','inné','âme','préjugés','désapprendre','ignorance','bonheur']},
{id:'q290',s:'s16',t:'courte',q:'Pourquoi, selon Socrate, aucune passion ne devrait faire obstacle à la vertu ?',m:'<p>Parce que si notre jugement était sain et que nous concevions correctement le bien, nous verrions que c\'est la vertu qui apporte le bonheur. Personne ne désire être malheureux; donc celui qui connaît vraiment le bien le choisit. Si nous faisons le mal, c\'est par ignorance du bien, pas par choix éclairé.</p>',k:['jugement sain','bien','bonheur','ignorance']},

// ---------------- s17 : procès
{id:'q300',s:'s17',t:'qcm',q:'De quoi Socrate est-il officiellement accusé ?',o:['Trahison et vol','Corrompre la jeunesse et introduire de nouvelles divinités dans la cité','Tyrannie','Enseigner la rhétorique contre paiement'],a:1,w:'Il est condamné à mort en 399 av. J.-C.'},
{id:'q301',s:'s17',t:'qcm',q:'Que répond Socrate à l\'accusation de se faire rémunérer ?',o:['Qu\'il gagne très peu','Que la vertu ne peut être troquée contre de l\'argent; sa mission était d\'être un guide dans la recherche de la vérité','Qu\'il rembourse ses élèves','Qu\'il n\'a jamais enseigné'],a:1,w:'Contrairement aux sophistes, il ne vend pas un savoir.'},
{id:'q302',s:'s17',t:'qcm',q:'En quelle année Socrate est-il condamné à mort ?',o:['470 av. J.-C.','399 av. J.-C.','440 av. J.-C.','323 av. J.-C.'],a:1,w:'Socrate vit de 470 à 399 av. J.-C.'},
{id:'q303',s:'s17',t:'qcm',q:'Quel texte de Platon rapporte les propos de Socrate à son procès ?',o:['Le Théétète','L\'Apologie de Socrate','La République','L\'Euthyphron'],a:1,w:'L\'Apologie (la défense) de Socrate.'},
{id:'q304',s:'s17',t:'qcm',q:'Selon le cours, que reproche-t-on réellement à Socrate ?',o:['D\'avoir remis en question la démocratie','D\'être riche','D\'être un sophiste','D\'avoir voyagé'],a:0,w:'En réalité, il remettait en question ce qui empêchait la démocratie de bien fonctionner.'},
{id:'q305',s:'s17',t:'qcm',q:'Que répond Socrate à l\'accusation de faire que l\'argument le plus faible l\'emporte ?',o:['Qu\'il en est fier','Qu\'on le confond avec les sophistes','Qu\'il ne parle jamais en public','Que c\'est Platon qui le fait'],a:1,w:'Le discours double est une technique des sophistes, pas la sienne.'},
{id:'q306',s:'s17',t:'qcm',q:'Selon l\'Apologie, pourquoi les hommes puissants d\'Athènes voulaient-ils se débarrasser de Socrate ?',o:['Parce qu\'il était trop riche','Parce qu\'il démasquait leur prétention et leur ignorance, et que leurs fils leur répondaient avec sa méthode','Parce qu\'il voulait devenir roi','Parce qu\'il refusait de voter'],a:1,w:'Un procès politique déguisé en procès pour impiété.'},
{id:'q307',s:'s17',t:'qcm',q:'Selon Socrate, qu\'exige la démocratie directe de ses citoyens ?',o:['Qu\'ils soient riches','Qu\'ils soient tous vertueux et justes, donc qu\'ils sachent ce qu\'est la justice','Qu\'ils soient guerriers','Qu\'ils suivent les sophistes'],a:1,w:'Or la majorité se laisse influencer par les préjugés et les opinions plutôt que par la vérité.'},
{id:'q308',s:'s17',t:'qcm',q:'Que répond Socrate à l\'accusation de rendre les jeunes athées ?',o:['Qu\'il est effectivement athée','Qu\'il n\'est pas athée et ne rejette pas les dieux de la cité','Que les dieux n\'existent pas','Qu\'il ne parle jamais de religion'],a:1,w:'Il rejette l\'accusation d\'impiété.'},
{id:'q309',s:'s17',t:'vf',q:'Selon Socrate, il suffit de se croire moralement bon pour l\'être.',a:false,w:'Faux. La vertu nécessite des efforts, un examen de soi et une recherche constante de la vérité.'},
{id:'q310',s:'s17',t:'vf',q:'Socrate questionnait les sophistes parce qu\'ils prétendaient dicter la conduite des autres sans connaître la justice ni le bien commun.',a:true,w:'Vrai.'},
{id:'q311',s:'s17',t:'courte',q:'Quelles sont les accusations portées contre Socrate et que répond-il à chacune ?',m:'<ul><li><b>Faire que l\'argument le plus faible l\'emporte</b> : on le confond avec les sophistes.</li><li><b>Se faire rémunérer</b> : la vertu ne peut être troquée contre de l\'argent; sa mission était d\'être un guide dans la recherche de la vérité.</li><li><b>Rendre les jeunes athées en étudiant la nature</b> : il n\'est pas athée et ne rejette pas les dieux de la cité.</li></ul><p>Accusations officielles : corrompre la jeunesse et introduire de nouvelles divinités.</p>',k:['sophistes','argent','vérité','athée','dieux de la cité','corrompre la jeunesse','divinités']},
{id:'q312',s:'s17',t:'courte',q:'Pourquoi le procès de Socrate est-il un procès politique ?',m:'<p>Ce qu\'on lui reproche réellement, c\'est d\'avoir remis en question la démocratie. En fait, il remettait en question ce qui l\'empêchait de bien fonctionner : la démocratie directe exige des citoyens vertueux qui savent ce qu\'est la justice, sinon chacun veille à son intérêt et elle dégénère en tyrannie et en loi du plus fort (Laramée). Or la majorité suivait les préjugés et les opinions, et les sophistes prétendaient dicter la conduite sans connaître la justice. Les puissants voulaient se débarrasser de celui qui démasquait leur ignorance.</p>',k:['démocratie','vertueux','justice','intérêt','tyrannie','préjugés','ignorance']},

// ---------------- s18 : justice et lois
{id:'q320',s:'s18',t:'qcm',q:'Quelle est la définition socratique de la justice ?',o:['La loi du plus fort','La vertu qui nous dicte de ne jamais commettre le mal','Ce que la majorité décide','Obéir aux dieux'],a:1,w:'Le terme « jamais » a un sens absolu.'},
{id:'q321',s:'s18',t:'qcm',q:'Pourquoi Socrate refuse-t-il de fuir la prison ?',o:['Il est trop vieux','Désobéir aux lois serait commettre le mal et se placer au-dessus des lois de la cité','Il n\'a pas d\'amis','Il espère être gracié'],a:1,w:'Il préfère mourir en étant vertueux, en adéquation avec ses propres principes.'},
{id:'q322',s:'s18',t:'qcm',q:'Contrairement aux sophistes, Socrate distingue :',o:['Le beau et le laid','Le juste et le légal','La nature et le feu','L\'être et le non-être'],a:1,w:'Pour Protagoras, justice et légalité sont synonymes. Pour Socrate, la justice n\'est pas la même chose que les lois.'},
{id:'q323',s:'s18',t:'qcm',q:'Selon Socrate, que doit utiliser le législateur pour établir les lois ?',o:['La rhétorique','La compréhension universelle de la justice','La force','Les oracles'],a:1,w:'Les lois sont des copies imparfaites de la justice, mais elles la visent.'},
{id:'q324',s:'s18',t:'qcm',q:'Pourquoi ne faut-il pas répondre au mal par le mal selon Socrate ?',o:['Parce que c\'est illégal','Parce qu\'on se montre semblable aux méchants, on commet le mal envers soi-même et on risque de rendre les méchants plus méchants','Parce que les dieux punissent','Parce que c\'est inutile'],a:1,w:'Le « jamais » de la définition est absolu : même la vengeance est exclue.'},
{id:'q325',s:'s18',t:'qcm',q:'Pourquoi, selon Socrate, ne faut-il jamais désobéir aux lois ?',o:['Parce qu\'elles sont parfaites','Parce que la justice véritable est visée à travers elles, et que leur désobéir mènerait au chaos','Parce que le plus fort les impose','Parce que la majorité les a votées'],a:1,w:'Même si les lois sont des copies imparfaites de la justice.'},
{id:'q326',s:'s18',t:'vf',q:'Pour Socrate, la justice et la légalité sont synonymes.',a:false,w:'Faux. C\'est la position de Protagoras. Socrate distingue le juste et le légal.'},
{id:'q327',s:'s18',t:'vf',q:'Socrate se soumet à la décision du tribunal même s\'il la juge injuste.',a:true,w:'Vrai, pour rester en adéquation avec ses principes.'},
{id:'q328',s:'s18',t:'vf',q:'Selon Socrate, la vengeance est acceptable quand on a subi une injustice.',a:false,w:'Faux. En agissant par vengeance, on commet le mal envers soi-même et sa raison.'},
{id:'q329',s:'s18',t:'courte',q:'Donne la définition socratique de la justice et explique le sens du mot « jamais ».',m:'<p>« La justice est la vertu qui nous dicte de <b>ne jamais commettre le mal</b>. » Le « jamais » est absolu : même en réponse au mal, on ne doit pas faire le mal, car on se montrerait semblable aux méchants, on commettrait le mal envers soi-même et sa raison (la vengeance), et on risquerait de rendre les méchants encore plus méchants.</p>',k:['ne jamais commettre le mal','absolu','semblable aux méchants','vengeance','raison']},
{id:'q330',s:'s18',t:'courte',q:'Pourquoi Socrate accepte-t-il sa condamnation plutôt que de fuir ?',m:'<p>Parce que sa définition de la justice implique de ne jamais désobéir aux lois : la justice véritable est visée à travers elles, même si elles en sont des copies imparfaites, et leur désobéir mènerait au chaos. Fuir reviendrait à se placer au-dessus des lois de la cité et à commettre le mal. Il préfère mourir en étant vertueux, en adéquation avec ses principes.</p>',k:['désobéir','copies imparfaites','chaos','au-dessus des lois','vertueux','principes']},
{id:'q331',s:'s18',t:'courte',q:'Explique la différence entre le juste et le légal chez Socrate, et compare avec les sophistes.',m:'<p>Pour Socrate, la justice n\'est pas la même chose que les lois : le législateur doit utiliser la compréhension universelle de la justice pour établir des lois, qui n\'en sont que des copies imparfaites. Chez Protagoras, au contraire, justice et légalité sont synonymes (juste = ce que la majorité décide), et chez Thrasymaque ou Calliclès, la justice est la loi du plus fort.</p>',k:['universelle','copies imparfaites','synonymes','majorité','plus fort']},

// ---------------- développement (rattachés à une fiche pour le filtre)
{id:'d001',s:'s8',t:'dev',q:'La démocratie athénienne est-elle juste ? Rédige un plan d\'argumentation : introduction (sujet amené, posé, divisé), deux arguments, une objection.',m:'<p><b>Introduction.</b> Sujet amené : au 5<sup>e</sup> siècle, Athènes invente un régime où le peuple gouverne directement. Sujet posé : ce régime est-il juste ? Sujet divisé : deux raisons de dire oui, puis une objection.</p><p><b>Argument 1.</b> Le pouvoir circule : tirage au sort des conseillers et des juges, ostracisme contre les trop influents; les lois sont au-dessus de tous.</p><p><b>Argument 2.</b> Égalité de parole : tout citoyen, sans distinction de classe, s\'exprime à l\'Assemblée et vote les lois; les taxes réduisent les écarts de richesse.</p><p><b>Objection.</b> Le mot « citoyen » exclut femmes, esclaves et étrangers, et le régime est vulnérable aux beaux parleurs : les sophistes poussent le peuple à des décrets contraires aux lois; selon Platon, la démocratie dégénère en tyrannie par excès de liberté.</p>'},
{id:'d002',s:'s3',t:'dev',q:'Comment la pensée mythique se présente-t-elle de nos jours ? Donne trois exemples et montre en quoi ils correspondent aux traits du mythe.',m:'<p><b>Thèse.</b> La pensée mythique n\'a pas disparu, car un nouveau mode de pensée est un ajout, pas un remplacement.</p><ul><li><b>L\'astrologie</b> : des forces externes (les astres) expliquent ma journée; on y trouve un ordre du temps et un sens donné à la vie.</li><li><b>Les superstitions des sportifs</b> : un rituel pour s\'attirer la faveur du sort, comme la religion primitive avec ses rituels.</li><li><b>Les théories du complot</b> : un récit avec des personnages cachés qui expliquent des phénomènes mystérieux, avec des bons et des méchants (valeur morale).</li></ul><p><b>Conclusion.</b> Dans chaque cas : un récit, des forces externes, une valeur morale, et aucune justification rationnelle universelle (la doxa).</p>'},
{id:'d003',s:'s12',t:'dev',q:'Les individus respecteraient-ils les lois s\'ils pouvaient agir sans conséquences ? Prends position avec deux exemples concrets.',m:'<p><b>Position.</b> Une partie des gens ne les respecterait pas, ce qui donne raison à Glaucon, mais pas tous, ce qui donne raison à Socrate.</p><p><b>Exemple 1 (Glaucon).</b> Sur l\'autoroute, la majorité dépasse la limite quand il n\'y a pas de radar; c\'est le berger de Lydie : sans risque de représailles, la loi devient un simple calcul (Thrasymaque).</p><p><b>Exemple 2 (Socrate).</b> Des gens rapportent un portefeuille trouvé sans témoin. Ils obéissent non par peur mais parce que commettre le mal les rendrait semblables aux méchants et nuirait à leur âme : la justice est la vertu de ne jamais commettre le mal.</p><p><b>Conclusion.</b> La question départage les deux camps : pour les sophistes de la loi du plus fort, le respect de la loi n\'est jamais volontaire; pour Socrate, celui qui connaît le bien le choisit même sans surveillance (vertu-science).</p>'},
{id:'d004',s:'s15',t:'dev',q:'Une action est-elle bonne parce qu\'une autorité l\'approuve, ou pour des raisons indépendantes de cette autorité ? Position, argument, exemple.',m:'<p><b>Position.</b> Une action est bonne pour des raisons indépendantes de l\'autorité qui l\'approuve (la deuxième branche du dilemme d\'Euthyphron).</p><p><b>Argument.</b> Si le bien dépendait de l\'approbation d\'une autorité, une même action deviendrait bonne ou mauvaise selon qui commande, et il serait impossible de critiquer une loi injuste. Or nous jugeons parfois qu\'une autorité se trompe, ce qui suppose un critère extérieur à elle : le bien a une essence (Socrate), il n\'est pas arbitraire.</p><p><b>Exemple.</b> La ségrégation raciale était légale et approuvée par l\'État; on la juge pourtant injuste. L\'approbation de l\'autorité ne suffit donc pas à rendre une action bonne.</p><p><b>Contre-position à mentionner.</b> Les sophistes (Protagoras) : le juste est ce que la majorité décide par convention.</p>'},
{id:'d005',s:'s16',t:'dev',q:'Es-tu d\'accord avec l\'idée que le mal vient de l\'ignorance ? Un argument rationnel et un exemple.',m:'<p><b>Thèse de Socrate.</b> Si nous faisons le mal, c\'est que nous avons de la difficulté à connaître le bien; qui connaît vraiment le bien agit bien, car la vertu apporte le bonheur (vertu-science).</p><p><b>Argument pour.</b> Celui qui vole croit que l\'argent le rendra heureux; s\'il savait que l\'injustice abîme son âme et ne mène pas au bonheur, il ne volerait pas. Son mal vient d\'une erreur de jugement, donc d\'une ignorance.</p><p><b>Objection.</b> On peut savoir qu\'une chose est mal et la faire quand même par faiblesse ou colère (fumer en connaissant les risques). Socrate répondrait que ce « savoir » n\'est qu\'une opinion, pas une vraie connaissance du bien.</p><p><b>Exemple.</b> Une personne qui se venge « sait » que la vengeance est mal, mais au moment d\'agir elle croit que cela lui fera du bien : elle ignore que la vengeance la rend semblable aux méchants (fiche 18).</p>'},
{id:'d006',s:'s16',t:'dev',q:'La politique devrait-elle être séparée de la morale ? Un argument rationnel et un exemple, en t\'appuyant sur Socrate et les sophistes.',m:'<p><b>Position sophiste (oui).</b> L\'homme d\'État cherche l\'utile, pas le bien : il fait adopter par la rhétorique les opinions les plus utiles à la cohésion, même des fictions (Protagoras). Exemple : un gouvernement qui exagère une menace pour unir la population.</p><p><b>Position socratique (non).</b> La démocratie directe exige des citoyens vertueux; si chacun ne veille qu\'à son intérêt, elle dégénère en tyrannie et en loi du plus fort (Laramée, p. 134). Le législateur doit utiliser la compréhension universelle de la justice. Exemple : un décret voté par la foule contre les lois existantes (fin du 5<sup>e</sup> siècle) mène au désordre total.</p><p><b>Conclusion.</b> Séparer politique et morale, c\'est remplacer le bien par l\'utile; Socrate montre où cela a mené Athènes.</p>'},
{id:'d007',s:'s18',t:'dev',q:'Est-il justifié d\'aller à l\'encontre d\'une loi ? Position, un exemple, un contre-exemple.',m:'<p><b>Position.</b> Il peut être justifié de désobéir à une loi injuste, mais ouvertement et en acceptant les conséquences; sinon on retombe dans la loi du plus fort (désobéir quand on ne risque rien).</p><p><b>Exemple.</b> Rosa Parks refuse de céder sa place en 1955 : la loi de ségrégation est légale mais injuste (le juste diffère du légal), et sa désobéissance publique fait changer la loi.</p><p><b>Contre-exemple.</b> Socrate refuse de fuir la prison : désobéir en secret reviendrait à se placer au-dessus des lois et à commettre le mal contre la cité; les lois, même copies imparfaites de la justice, la visent, et leur désobéir mène au chaos.</p><p><b>Nuance.</b> Socrate lui-même distingue le juste et le légal, ce qui permet de critiquer une loi sans la violer en cachette.</p>'},
{id:'d008',s:'s19',t:'dev',q:'Compare la conception de la vérité et de la justice chez les sophistes et chez Socrate.',m:'<p><b>Vérité.</b> Sophistes : relative et subjective; la science est la sensation, tout est subjectif, la vérité est remplacée par la vraisemblance. Socrate : universelle; les concepts ont une essence, le bien n\'est pas arbitraire; le logos vise la justification, pas la persuasion.</p><p><b>Justice.</b> Sophistes : justice = légalité, juste tant que la majorité le croit (Protagoras), ou loi du plus fort (Thrasymaque, Calliclès). Socrate : la vertu de ne jamais commettre le mal; le juste diffère du légal, mais on obéit aux lois parce qu\'elles visent la justice.</p><p><b>Conséquence.</b> Le sophiste vend des recettes pour réussir; Socrate questionne pour faire accoucher le bien inné (vertu-science). Doxa contre logos.</p>'},
{id:'d009',s:'s5',t:'dev',q:'En quoi les présocratiques marquent-ils le passage du mythe à la raison ? Appuie-toi sur leurs trois innovations et sur un exemple de philosophe.',m:'<p><b>Le passage.</b> On ne raconte plus d\'histoires : l\'ordre divin est arbitraire, on cherche un procédé qui rende compte de la stabilité du monde, et la nature contient ses propres principes.</p><p><b>Innovation 1, immanence.</b> Des principes internes à la nature dont on peut faire l\'expérience (le feu d\'Héraclite, les atomes de Démocrite), contre les dieux extérieurs d\'Hésiode.</p><p><b>Innovation 2, intelligibilité.</b> La nature est un tout ordonné, compréhensible en elle-même : Héraclite voit une loi stable derrière le changement, saisie par le logos.</p><p><b>Innovation 3, économie.</b> Un seul principe explique tout (le nombre chez Pythagore) au lieu d\'une foule de divinités.</p><p><b>Exemple.</b> Xénophane critique l\'anthropomorphisme des dieux d\'Homère et d\'Hésiode et propose un dieu rationnel : c\'est le début des lumières grecques.</p>'},
{id:'d010',s:'s14',t:'dev',q:'Explique comment Socrate utilise ses trois méthodes dans le dialogue d\'Euthyphron.',m:'<p><b>Elenchos.</b> Euthyphron propose une définition (le pieux est ce qui plaît aux dieux); Socrate l\'accepte provisoirement, questionne (les dieux sont-ils d\'accord entre eux ?), et révèle la contradiction (une même chose serait pieuse et impie).</p><p><b>Aporie.</b> Après quatre définitions réfutées, Euthyphron ne sait plus ce qu\'il croyait savoir et s\'enfuit : l\'illusion du savoir est détruite, il incarne l\'ignorance qui s\'ignore.</p><p><b>Maïeutique.</b> Socrate ne donne jamais la réponse : il tente de faire accoucher Euthyphron d\'une définition viable. Le dialogue échoue, mais la méthode est visible : la vérité devrait émerger de l\'interlocuteur lui-même.</p><p><b>Lien.</b> Le dilemme (aimé parce que pieux, ou pieux parce qu\'aimé ?) montre que Socrate cherche l\'essence de la piété, pas une autorité qui l\'approuve.</p>'}
];
